    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

scwin.listSync = async function() {

    //----W-Craft WebSquare 변환 확인: NameValue----//
    url += "&FILE_RCV_STAT_CD=" + MxDataSet_code2.NameValue(MxCombo2.Index + 1, "CD_VAL") + "&DISCLS_KIND_CD=" + MxDataSet_code3.NameValue(MxCombo3.Index + 1, "CD_VAL");
    url += "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_MxDataSet",
        action : "/rcvfile.do",
        ref : "",
        target : "MxDataSet=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

